mapper.select:
SELECT p.id as pledgeId, pj.id as projectId, pj.title as projectTitle, p.reward_id as rewardId, r.title as rewardTitle, p.amount as amount, p.status as status, p.fulfillment_status as fulfillmentStatus, p.created_at as pledgedAt FROM pledge p JOIN project pj ON p.project_id = pj.id LEFT JOIN reward r ON p.reward_id = r.id WHERE p.user_id = #{userId}
AND p.fulfillment_status = #{fulfillmentStatus}
AND p.status = #{pledgeStatus}
AND (p.created_at < #{cursorCreatedAt} OR (p.created_at = #{cursorCreatedAt} AND p.id < #{cursorId}))
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit}
